using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Net;using System.Security.Cryptography;using System.Collections.Generic;using System.Threading;using System.Diagnostics;
namespace Glint {
static class SpeechToText {
 internal const string ModelHash="ae85e4a935d7a567bd102fe55afc16bb595bdb618e11b2fc7591bc08120411bb";
 internal static string Cache=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Kaiwu","speech");
 internal static string ModelPath {get{return Path.Combine(Cache,"ggml-small-q5_1.bin");}}
 internal static bool Ready {get{return File.Exists(ModelPath)&&new FileInfo(ModelPath).Length==190085487;}}
 internal sealed class Result {public string text,srt,method;}
 internal static Result Subtitles(string value){var blocks=Regex.Split(value.Replace("\r",""),@"\n\s*\n");var text=new StringBuilder();var srt=new StringBuilder();int index=0;foreach(string block in blocks){var match=Regex.Match(block,@"(?m)^(\d{1,2}:)?\d{2}:\d{2}[,.]\d{3}\s*-->\s*(?:\d{1,2}:)?\d{2}:\d{2}[,.]\d{3}[^\n]*\n");if(!match.Success)continue;string line=Regex.Replace(block.Substring(match.Index+match.Length),"<[^>]+>|\\{[^}]+\\}","").Trim();if(line.Length==0)continue;string times=match.Value.Trim();var pair=times.Split(new[]{"-->"},StringSplitOptions.None);Func<string,string> normalized=t=>{var m=Regex.Match(t.Trim(),@"^(?:(\d{1,2}):)?(\d{2}):(\d{2})[,.](\d{3})");return (m.Groups[1].Success?m.Groups[1].Value.PadLeft(2,'0'):"00")+":"+m.Groups[2].Value+":"+m.Groups[3].Value+","+m.Groups[4].Value;};srt.Append(++index).Append('\n').Append(normalized(pair[0])).Append(" --> ").Append(normalized(pair[1])).Append('\n').Append(line).Append("\n\n");text.AppendLine(line);}return index==0?null:new Result{text=text.ToString().Trim(),srt=srt.ToString(),method="同名字幕"};}
 internal static void Prepare(Action<string,long,long> report,CancellationToken cancel){if(Ready)return;Directory.CreateDirectory(Cache);string temp=ModelPath+"."+Guid.NewGuid().ToString("N")+".part";try{var request=(HttpWebRequest)WebRequest.Create("https://huggingface.co/ggerganov/whisper.cpp/resolve/f281eb45af861ab5e5297d23694b7d46e090c02c/ggml-small-q5_1.bin");request.UserAgent="Kaiwu/0.4";request.Timeout=30000;request.ReadWriteTimeout=30000;using(cancel.Register(()=>request.Abort()))using(var response=request.GetResponse())using(var input=response.GetResponseStream())using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write)){byte[] buffer=new byte[65536];int n;long done=0;var clock=Stopwatch.StartNew();while((n=input.Read(buffer,0,buffer.Length))>0){cancel.ThrowIfCancellationRequested();output.Write(buffer,0,n);done+=n;if(clock.ElapsedMilliseconds>150){report("正在准备离线识别模型",done,190085487);clock.Restart();}}}report("正在校验识别模型",0,-1);using(var hash=SHA256.Create())using(var file=File.OpenRead(temp))if(BitConverter.ToString(hash.ComputeHash(file)).Replace("-","").ToLowerInvariant()!=ModelHash)throw new IOException("识别模型下载不完整，请重试。");cancel.ThrowIfCancellationRequested();if(File.Exists(ModelPath))File.Delete(ModelPath);File.Move(temp,ModelPath);}finally{if(File.Exists(temp))File.Delete(temp);}}
 internal static Result Extract(string source,string language,bool preferSubtitles,Action<string,long,long> report,CancellationToken cancel){if(preferSubtitles)foreach(string ext in new[]{".srt",".vtt"}){string sidecar=Path.ChangeExtension(source,ext);if(File.Exists(sidecar)){var result=Subtitles(File.ReadAllText(sidecar));if(result!=null)return result;}}
 Prepare(report,cancel);string folder=Path.Combine(Path.GetTempPath(),"kaiwu-speech-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string wav=Path.Combine(folder,"audio.wav"),prefix=Path.Combine(folder,"transcript");try{Audio(source,wav,report,cancel);cancel.ThrowIfCancellationRequested();string exe=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"helpers","speech","whisper-cli.exe");if(!File.Exists(exe))throw new IOException("离线识别组件缺失，请重新解压开物。");if(!new[]{"auto","zh","en"}.Contains(language))language="zh";string args="-m \""+ModelPath+"\" -f \""+wav+"\" -of \""+prefix+"\" -l "+language+" -t "+Math.Max(1,Math.Min(8,Environment.ProcessorCount/2))+" -otxt -osrt -pp -ng"+(language=="zh"?" --prompt \"以下是简体中文的语音转写。\"":"");report("正在识别语音",0,100);using(var p=new Process{StartInfo=new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8}}){p.OutputDataReceived+=(s,e)=>{};p.ErrorDataReceived+=(s,e)=>{if(e.Data==null)return;var m=Regex.Match(e.Data,@"progress\s*=\s*(\d+)%");if(m.Success)report("正在识别语音",int.Parse(m.Groups[1].Value),100);};p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();var clock=Stopwatch.StartNew();while(!p.WaitForExit(200)){if(cancel.IsCancellationRequested||clock.Elapsed.TotalHours>3){p.Kill();p.WaitForExit();cancel.ThrowIfCancellationRequested();throw new IOException("识别超时，请分段处理。");}}p.WaitForExit();if(p.ExitCode!=0)throw new IOException("语音识别失败，请检查文件音轨。错误码："+p.ExitCode);}
 string txt=prefix+".txt",sub=prefix+".srt";if(!File.Exists(txt)||!File.Exists(sub))throw new IOException("没有生成识别结果。");string text=File.ReadAllText(txt,Encoding.UTF8).Trim();if(text.Length==0)throw new IOException("没有识别到语音。");return new Result{text=text,srt=File.ReadAllText(sub,Encoding.UTF8),method="本机语音识别"};}finally{foreach(string file in Directory.GetFiles(folder))File.Delete(file);Directory.Delete(folder);}}
 static void Audio(string source,string wav,Action<string,long,long> report,CancellationToken cancel){report("正在读取音轨",0,-1);var options=new Dictionary<string,string>{{"config","no"},{"terminal","no"},{"idle","yes"},{"keep-open","no"},{"vid","no"},{"sid","no"},{"o",wav},{"of","wav"},{"oac","pcm_s16le"},{"audio-samplerate","16000"},{"audio-channels","mono"}};using(var engine=new Engine(options)){if(engine.Command("loadfile",source,"replace")<0)throw new IOException("无法读取这个媒体文件。");var clock=Stopwatch.StartNew();var progress=Stopwatch.StartNew();while(true){cancel.ThrowIfCancellationRequested();if(clock.Elapsed.TotalHours>1)throw new IOException("读取音轨超时。");IntPtr e=Native.mpv_wait_event(engine.Handle,.1);int id=System.Runtime.InteropServices.Marshal.ReadInt32(e);if(id==7){IntPtr data=System.Runtime.InteropServices.Marshal.ReadIntPtr(e,16);if(System.Runtime.InteropServices.Marshal.ReadInt32(data)!=0)throw new IOException("没有可用的音轨，或音轨无法解码。");break;}if(progress.ElapsedMilliseconds>200){report("正在读取音轨",(long)(engine.Number("time-pos")*1000),(long)(engine.Number("duration")*1000));progress.Restart();}}}if(!File.Exists(wav)||new FileInfo(wav).Length<100)throw new IOException("没有找到可识别的音轨。");}
}
}
